import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;



public class MBPP_255_combinations_colors {
    // Write a function that takes in an array array list and length n, and generates all combinations (with repetition) of the elements of the array list and returns an array array list with an array array list for each combination.

    // Write a function that takes in an array array list and length n, and generates all combinations (with repetition) of the elements of the array list and returns an array array list with an array array list for each combination.
    public static List<List<String>> combinationsColors(List<String> l, int n) {
        return combinations(l, n).collect(Collectors.toList());
    }

    private static Stream<List<String>> combinations(List<String> list, int k) {
        if (k == 1) {
            return list.stream().map(e -> List.of(e));
        } else {
            return list.stream().flatMap(e -> combinations(list.stream().filter(f -> !f.equals(e)).collect(Collectors.toList()), k - 1).stream().map(f -> List.of(e, f)));
        }
    }

}

