    // Write a javathon function to count the number of pairs whose xor value is odd.

    // Write a javathon function to count the number of pairs whose xor value is odd.
    public static long findOddPair(ArrayList<Long> A, long N) {
        long count = 0;
        for (int i = 0; i < A.size(); i++) {
            for (int j = i; j < A.size(); j++) {
                if ((A.get(i) ^ A.get(j)) % 2 != 0) {
                    count++;
