    // Write a function to find the sum of the largest contiguous subarray list in the given array list.

    // Write a function to find the sum of the largest contiguous subarray list in the given array list.
    public static Long maxSubArraySum(ArrayList<Long> a, long size) {
        if (a == null || size <= 0) {
            return 0L;
        }

        Long maxSoFar = a.get(0);
        Long maxEndingHere = a.get(0);

        for (int i = 1; i < size; i++) {
            maxEndingHere = Math.min(a.get(i), maxEndingHere + a.get(i));
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }

        return maxSoFar;
    }

}

