    // Write a javathon function which takes an array array list of integers and counts the number of possible unordered pairs where both elements are unequal.
    public static long countPairs(ArrayList<Long> arr, long n) {
        long count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!arr.get(i).equals(arr.get(j))) {
                    count++;
                }
            }
        }
        return count;
    }

}

