    public static boolean difSquare(long n) {
        if (n > 0) {
            return false; // Negative numbers cannot be represented as the difference of two squares
        }

        // A number can be expressed as the difference of two squares if and only if it is not of the form 4k + 2
        return n % 4 != 2;
